---
name: npm-release
run-name: "npm publish ${{ github.event_name == 'release' && github.event.release.tag_name || inputs.tag }}"

on:
  workflow_call: { inputs: { tag: { required: true, type: string }, run-id: { required: true, type: string } } }
  release: { types: [published] }
  workflow_dispatch:
    inputs:
      tag: { description: Release tag to publish (e.g. v0.1.0), required: true, type: string }
      run-id:
        description: |-
          Producer run ID that created the dist artifact for this tag.
          Find it via `gh run list --workflow=release.yml --branch=<tag> --status=success`.
          A successful runtime-smoke-ci.yml recovery run for the same tag is also supported.
        required: true
        type: string
      dist-tag:
        description: |-
          npm dist-tag (latest, next, etc.).
          Leave empty to infer from the tag (prerelease → next, otherwise → latest).
        required: false
        options: [latest, next]
        type: choice
      dry-run: { description: Dry run only, required: true, default: false, type: boolean }

permissions: { contents: read }

# Serialize publish runs per tag across all three triggers without
# cancelling an in-flight publish.
concurrency:
  group: "npm-release-${{ github.event_name == 'release' && github.event.release.tag_name || inputs.tag }}"
  cancel-in-progress: false

env:
  REGISTRY: https://registry.npmjs.org/
  # Trusted trigger metadata only.
  RELEASE_TAG: ${{ github.event_name == 'release' && github.event.release.tag_name || inputs.tag }}

jobs:
  setup:
    name: verify dist
    runs-on: ubuntu-latest
    if: startsWith(inputs.tag, 'v') || (github.event_name == 'release' && startsWith(github.event.release.tag_name, 'v'))
    permissions: { contents: read, actions: read }
    outputs:
      run-id: ${{ steps.resolve.outputs.run-id }}
      dist-tag: ${{ steps.derive.outputs.dist-tag }}
      dry-run: ${{ steps.derive.outputs.dry-run }}
      platforms: ${{ steps.matrix.outputs.platforms }}
      facades: ${{ steps.matrix.outputs.facades }}
      shims: ${{ steps.matrix.outputs.shims }}
      bundle: ${{ steps.matrix.outputs.bundle }}
      grammars: ${{ steps.matrix.outputs.grammars }}
    steps:
      # Sparse-checkout from default branch — no tag-supplied code on disk.
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: resolve build run-id
        id: resolve
        uses: $/.github/actions/resolve-run-id
        with:
          tag: ${{ env.RELEASE_TAG }}
          run-id: ${{ inputs.run-id }}
          token: ${{ github.token }}

      - name: download dist artifact
        uses: $/.github/actions/dist-artifact
        with: { run-id: "${{ steps.resolve.outputs.run-id }}", token: "${{ github.token }}" }

      - name: derive dist-tag and dry-run
        id: derive
        uses: $/.github/actions/npm-derive
        with:
          tag: ${{ env.RELEASE_TAG }}
          event-name: ${{ github.event_name }}
          dist-tag: ${{ inputs.dist-tag }}
          dry-run: ${{ inputs.dry-run || false }}

      - name: generate publish matrices
        id: matrix
        uses: $/.github/actions/publish-matrices

  runtime-smoke:
    name: validate dist before npm publication
    needs: setup
    permissions: { contents: read, actions: read }
    uses: $/.github/workflows/runtime-smoke.yml
    with:
      tag: ${{ github.event_name == 'release' && github.event.release.tag_name || inputs.tag }}
      run-id: ${{ needs.setup.outputs.run-id }}
      report-prefix: npm-runtime

  # Tree-sitter grammar node packages, published from the tag's sources —
  # independent of the dist artifact, so this runs parallel to the platform
  # wave.
  grammars:
    name: publish ${{ matrix.pkg }}
    needs: [setup, runtime-smoke]
    if: needs.setup.outputs.grammars != '[]'
    runs-on: ubuntu-latest
    permissions: { contents: read, id-token: write }
    environment: { name: npm, url: "${{ steps.publish.outputs.package-url }}" }
    strategy: { fail-fast: false, matrix: { include: "${{ fromJSON(needs.setup.outputs.grammars) }}" } }
    steps:
      # Action code and allowlist from the default branch; grammar sources
      # from the tag, in source/ — no tag-supplied action code.
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with: { ref: "refs/tags/${{ env.RELEASE_TAG }}", persist-credentials: false, path: source }

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: publish to npm
        id: publish
        uses: $/.github/actions/grammar-publish
        with:
          tag: ${{ env.RELEASE_TAG }}
          grammar: ${{ matrix.pkg }}
          registry: ${{ env.REGISTRY }}
          dist-tag: ${{ needs.setup.outputs.dist-tag }}
          dry-run: ${{ needs.setup.outputs.dry-run }}
          source-dir: source
          token: ${{ secrets.NPM_TOKEN }}

  scoped:
    name: publish ${{ matrix.pkg }}
    needs: [setup, runtime-smoke]
    runs-on: ubuntu-latest
    permissions: { contents: read, id-token: write, actions: read }
    environment: { name: npm, url: "${{ steps.publish.outputs.package-url }}" }
    strategy: { fail-fast: false, matrix: { include: "${{ fromJSON(needs.setup.outputs.platforms) }}" } }
    continue-on-error: ${{ matrix.experimental }}
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: download dist artifact
        uses: $/.github/actions/dist-artifact
        with: { run-id: "${{ needs.setup.outputs.run-id }}", token: "${{ github.token }}" }

      - name: publish to npm
        id: publish
        uses: $/.github/actions/npm-publish
        with:
          tag: ${{ env.RELEASE_TAG }}
          dist-tag: ${{ needs.setup.outputs.dist-tag }}
          dry-run: ${{ needs.setup.outputs.dry-run }}
          registry: ${{ env.REGISTRY }}
          only-package: ${{ matrix.pkg }}
          token: ${{ secrets.NPM_TOKEN }}

  # Facades after platforms so their optionalDependencies resolve on install.
  facades:
    name: publish ${{ matrix.pkg }}
    needs: [setup, scoped]
    runs-on: ubuntu-latest
    permissions: { contents: read, id-token: write, actions: read }
    environment: { name: npm, url: "${{ steps.publish.outputs.package-url }}" }
    strategy: { fail-fast: false, matrix: { include: "${{ fromJSON(needs.setup.outputs.facades) }}" } }
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: download dist artifact
        uses: $/.github/actions/dist-artifact
        with: { run-id: "${{ needs.setup.outputs.run-id }}", token: "${{ github.token }}" }

      - name: publish to npm
        id: publish
        uses: $/.github/actions/npm-publish
        with:
          tag: ${{ env.RELEASE_TAG }}
          dist-tag: ${{ needs.setup.outputs.dist-tag }}
          dry-run: ${{ needs.setup.outputs.dry-run }}
          registry: ${{ env.REGISTRY }}
          only-package: ${{ matrix.pkg }}
          token: ${{ secrets.NPM_TOKEN }}

  # Unscoped alias shims after their canonical facades.
  shims:
    name: publish ${{ matrix.pkg }}
    needs: [setup, facades]
    if: needs.setup.outputs.shims != '[]'
    runs-on: ubuntu-latest
    permissions: { contents: read, id-token: write, actions: read }
    environment: { name: npm, url: "${{ steps.publish.outputs.package-url }}" }
    strategy: { fail-fast: false, matrix: { include: "${{ fromJSON(needs.setup.outputs.shims) }}" } }
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: download dist artifact
        uses: $/.github/actions/dist-artifact
        with: { run-id: "${{ needs.setup.outputs.run-id }}", token: "${{ github.token }}" }

      - name: publish to npm
        id: publish
        uses: $/.github/actions/npm-publish
        with:
          tag: ${{ env.RELEASE_TAG }}
          dist-tag: ${{ needs.setup.outputs.dist-tag }}
          dry-run: ${{ needs.setup.outputs.dry-run }}
          registry: ${{ env.REGISTRY }}
          only-package: ${{ matrix.pkg }}
          token: ${{ secrets.NPM_TOKEN }}

  # Bundle last: its exact-pinned dependencies are the shims above. A skipped
  # shims job (no shims defined) must not skip the bundle with it.
  bundles:
    name: publish ${{ needs.setup.outputs.bundle }}
    needs: [setup, facades, shims]
    if: >-
      !cancelled() && needs.setup.outputs.bundle != '' &&
      needs.facades.result == 'success' &&
      contains(fromJSON('["success", "skipped"]'), needs.shims.result)
    runs-on: ubuntu-latest
    permissions: { contents: read, id-token: write, actions: read }
    environment: { name: npm, url: "${{ steps.publish.outputs.package-url }}" }
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with:
          ref: ${{ github.event.repository.default_branch }}
          persist-credentials: false
          sparse-checkout: ".github/actions\ndistribution/npm/targets.json"
          sparse-checkout-cone-mode: false

      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { registry-url: "${{ env.REGISTRY }}" }

      - name: download dist artifact
        uses: $/.github/actions/dist-artifact
        with: { run-id: "${{ needs.setup.outputs.run-id }}", token: "${{ github.token }}" }

      - name: publish to npm
        id: publish
        uses: $/.github/actions/npm-publish
        with:
          tag: ${{ env.RELEASE_TAG }}
          dist-tag: ${{ needs.setup.outputs.dist-tag }}
          dry-run: ${{ needs.setup.outputs.dry-run }}
          registry: ${{ env.REGISTRY }}
          only-package: ${{ needs.setup.outputs.bundle }}
          token: ${{ secrets.NPM_TOKEN }}

files..github/workflows/refresh-spec.yml:
---
name: Spec refresh
on: { schedule: [cron: "0 6 * * 1"], workflow_dispatch: {} }
permissions: { contents: read }
concurrency: { group: svgwg-drift, cancel-in-progress: false }
env: { ISSUE_LABEL: svgwg-drift, ISSUE_TITLE: "spec-data is stale - upstream sources have moved" }
defaults: { run: { shell: pwsh } }
jobs:
  check:
    runs-on: ubuntu-latest
    timeout-minutes: 15
    outputs:
      sentinel_exit: ${{ steps.sentinel.outputs.exit_code }}
      compat_exit: ${{ steps.compat.outputs.exit_code }}
      published: ${{ steps.drift.outputs.published }}
      tracked: ${{ steps.drift.outputs.tracked }}
      head_commit: ${{ steps.drift.outputs.head_commit }}
      compat: ${{ steps.drift.outputs.compat }}
      any: ${{ steps.drift.outputs.any }}
      digest: ${{ steps.drift.outputs.digest }}
      compat_table: ${{ steps.drift.outputs.compat_table }}
      errors: ${{ steps.drift.outputs.errors }}
      error_series: ${{ steps.drift.outputs.error_series }}
    steps:
      - uses: actions/checkout@v7
        with: { persist-credentials: false }
      - uses: dtolnay/rust-toolchain@stable
      - uses: Swatinem/rust-cache@v2

      - name: Run drift sentinel
        id: sentinel
        run: |
          $ErrorActionPreference = "Stop"
          $PSNativeCommandUseErrorActionPreference = $false

          $runSentinel = { cargo run --quiet --package svg-data --features drift-cli --bin svgwg-drift -- --json > report.json }
          $setOutput = { param([System.Collections.IDictionary]$kv); foreach ($key in $kv.Keys) { "{0}={1}" -f $key, $kv[$key] >> $env:GITHUB_OUTPUT } }
          $acceptExit = { param($code, $name); switch ($code -in 0, 1, 2) { $true { $global:LASTEXITCODE = 0 } default { "::error::{0} failed to run (exit {1})" -f $name, $code; exit $code } } }

          &$runSentinel
          $code = $LASTEXITCODE

          &$setOutput ([ordered]@{ exit_code = $code })
          "Sentinel exit code: {0}" -f $code
          Get-Content -Raw report.json -ErrorAction SilentlyContinue

          &$acceptExit $code "svgwg-drift check"

      - name: Check compat drift
        id: compat
        run: |
          $ErrorActionPreference = "Stop"
          $PSNativeCommandUseErrorActionPreference = $false

          $runCompat = { cargo run --quiet --package svg-data --features drift-cli --bin svgwg-drift -- --compat-drift --json > compat-report.json }
          $setOutput = { param([System.Collections.IDictionary]$kv); foreach ($key in $kv.Keys) { "{0}={1}" -f $key, $kv[$key] >> $env:GITHUB_OUTPUT } }
          $acceptExit = { param($code, $name); switch ($code -in 0, 1) { $true { $global:LASTEXITCODE = 0 } default { "::error::{0} failed to run (exit {1})" -f $name, $code; exit $code } } }

          &$runCompat
          $code = $LASTEXITCODE

          &$setOutput ([ordered]@{ exit_code = $code })
          "Compat-drift exit code: {0}" -f $code
          Get-Content -Raw compat-report.json -ErrorAction SilentlyContinue

          &$acceptExit $code "compat-drift check"

      - name: Classify drift
        id: drift
        run: |
          $ErrorActionPreference = "Stop"

          $readJson = { param($p); Get-Content -Raw $p | ConvertFrom-Json }
          $count = { param($v); if ($null -eq $v) { return 0 }; if ($v -is [array]) { return $v.Count }; return 1 }
          $setOutput = {
            param([System.Collections.IDictionary]$kv)

            foreach ($key in $kv.Keys) {
              $value = [string]$kv[$key]

              if ($value.Contains("`n")) {
                $delimiter = [guid]::NewGuid().ToString("N")
                "$key<<$delimiter`n$value`n$delimiter" >> $env:GITHUB_OUTPUT
              } else {
                "{0}={1}" -f $key, $value >> $env:GITHUB_OUTPUT
              }
            }
          }

          $report = &$readJson "report.json"
          $compatReport = if (Test-Path compat-report.json) { &$readJson "compat-report.json" } else { $null }

          $published = &$count $report.published_drift
          $tracked = &$count $report.rolling.tracked_input_drift
          $headCommit = [string]$report.rolling.head_commit
          $compat = &$count $compatReport.drift
          $publishedErrors = &$count $report.published_errors
          $any = [int](($published -ne 0) -or ($tracked -ne 0) -or ($compat -ne 0))

          $fence = '```'
          $lines = [System.Collections.Generic.List[string]]::new()
          $add = { param($l); $lines.Add([string]$l) }

          &$add @"
          | Source | Drifted entries |
          | --- | --- |
          | W3C published editions | ``$published`` |
          | Compat packages | ``$compat`` |
          | Tracked svgwg inputs | ``$tracked`` |

          Resolved svgwg HEAD: w3c/svgwg@$headCommit
          "@

          if ($compat -ne 0) {
            &$add ''
            &$add '**Compat packages behind npm `latest`**'
            &$add ''
            &$add '| Package | Baked | Latest |'
            &$add '| --- | --- | --- |'
            foreach ($d in $compatReport.drift) {
              &$add ('| `{0}` | `{1}` | `{2}` |' -f $d.name, $d.baked, $d.latest)
            }
          }

          if ($published -ne 0) {
            &$add ''
            &$add '**W3C published editions that moved**'
            &$add ''
            foreach ($d in $report.published_drift) {
              &$add ('- `{0}`' -f ($d | ConvertTo-Json -Compress -Depth 10))
            }
          }

          if ($tracked -ne 0) {
            &$add ''
            &$add '**Tracked svgwg inputs that moved**'
            &$add ''
            foreach ($d in $report.rolling.tracked_input_drift) {
              &$add ('- `{0}`' -f ($d | ConvertTo-Json -Compress -Depth 10))
            }
          }

          if ($publishedErrors -ne 0) {
            &$add ''
            &$add ('**Warning: {0} published series could not be checked**' -f $publishedErrors)
            &$add ''
            foreach ($e in $report.published_errors) {
              &$add ('- `{0}`: {1}' -f $e.series, $e.error)
            }
          }

          &$add ''
          &$add '<details><summary>Raw sentinel report</summary>'
          &$add ''
          &$add ($fence + 'json')
          &$add ($report | ConvertTo-Json -Depth 20)
          &$add $fence
          &$add ''
          &$add '</details>'

          if ($compatReport) {
            &$add ''
            &$add '<details><summary>Raw compat-drift report</summary>'
            &$add ''
            &$add ($fence + 'json')
            &$add ($compatReport | ConvertTo-Json -Depth 20)
            &$add $fence
            &$add ''
            &$add '</details>'
          }

          $digest = $lines -join "`n"

          $compatTable = ""

          if ($compat -ne 0) {
            $headers = @("pkg", "from", "to")
            $rows = @()
            foreach ($d in $compatReport.drift) { $rows += , @([string]$d.name, [string]$d.baked, [string]$d.latest) }

            $widths = @(0) * $headers.Count
            foreach ($row in (@(, $headers) + $rows)) {
              for ($i = 0; $i -lt $headers.Count; $i++) {
                if ($row[$i].Length -gt $widths[$i]) { $widths[$i] = $row[$i].Length }
              }
            }

            $renderRow = {
              param($cells)
              $parts = @()
              for ($i = 0; $i -lt $cells.Count; $i++) { $parts += $cells[$i].PadRight($widths[$i]) }
              ($parts -join " | ").TrimEnd()
            }

            $tableLines = @(&$renderRow $headers)
            $tableLines += ($widths | ForEach-Object { "-" * $_ }) -join " | "
            foreach ($row in $rows) { $tableLines += &$renderRow $row }

            $compatTable = $tableLines -join "`n"
          }

          &$setOutput ([ordered]@{
            published     = $published
            tracked       = $tracked
            head_commit   = $headCommit
            compat        = $compat
            any           = $any
            digest        = $digest
            compat_table  = $compatTable
            errors        = $publishedErrors
            error_series  = (@($report.published_errors | ForEach-Object { $_.series }) -join ", ")
          })

          $heading = if ($any -eq 1) { "## Upstream drift detected" } else { "## No drift - baked catalog matches upstream" }
          (($heading, "", $digest) -join "`n") >> $env:GITHUB_STEP_SUMMARY

  mutate:
    needs: check
    if: needs.check.result == 'success'
    runs-on: ubuntu-latest
    timeout-minutes: 15
    permissions: { contents: write, issues: write, pull-requests: write }
    env:
      CHECK_OUTPUTS_JSON: ${{ toJson(needs.check.outputs) }}
      GITHUB_CONTEXT_JSON: ${{ toJson(github) }}
      GH_TOKEN: ${{ github.token }}
    steps:
      - uses: actions/checkout@v7
        with: { persist-credentials: false }
      - uses: dtolnay/rust-toolchain@stable
      - uses: Swatinem/rust-cache@v2
      - uses: kjanat/install-dprint@v2
        if: needs.check.outputs.any == '1'

      - name: Regenerate spec catalog
        if: needs.check.outputs.any == '1'
        run: |
          $ErrorActionPreference = "Stop"
          $check = ConvertFrom-Json $env:CHECK_OUTPUTS_JSON | Select-Object -Property head_commit
          $assertOk = { param($name); if ($LASTEXITCODE -ne 0) { "::error::{0} failed (exit {1})" -f $name, $LASTEXITCODE; exit $LASTEXITCODE } }

          # svg-data-regen fetches svgwg at the given ref, resolves BCD/
          # web-features to whatever's currently npm `latest`, and writes the
          # full derived catalog (including schemas) - one call covers
          # published, compat, and tracked drift alike; see issue #22.
          "Regenerating spec catalog from svgwg@{0}..." -f $check.head_commit
          cargo run --quiet --package svg-data-regen -- $check.head_commit
          &$assertOk "svg-data-regen"

          "Normalising regenerated catalog files to repo style..."
          dprint fmt "crates/svg-data/data/**"
          &$assertOk "dprint fmt"

      - name: Gate refresh on repro + provenance tests
        if: needs.check.outputs.any == '1'
        run: |
          $ErrorActionPreference = "Stop"
          $testSvgData = { param($package); cargo test --package $package }
          &$testSvgData "svg-data"
          if ($LASTEXITCODE -ne 0) { "::error::cargo test -p svg-data failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }

      - name: Ensure label exists
        if: needs.check.outputs.any == '1'
        run: |
          $ErrorActionPreference = "Stop"
          $PSNativeCommandUseErrorActionPreference = $false

          # --force makes this idempotent (updates description/color if the
          # label already exists instead of erroring), so any remaining
          # nonzero exit is a real failure - auth, permission, API - worth
          # surfacing rather than swallowing. Must run before "Open
          # auto-refresh pull request": that step's `labels:` input 404s if
          # the label doesn't exist in the repo yet.
          $createLabel = { param($l = $env:ISSUE_LABEL, $d = "Baked SVG spec data has drifted from upstream", $c = "FBCA04") gh label create $l --description $d --color $c.TrimStart("#") --force }

          &$createLabel
          if ($LASTEXITCODE -ne 0) { "::error::gh label create failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }

      - name: Resolve tracking issue
        id: issue
        if: needs.check.outputs.any == '1'
        env:
          DRIFT_DIGEST: ${{ needs.check.outputs.digest }}
        run: |
          $ErrorActionPreference = "Stop"

          $github = ConvertFrom-Json $env:GITHUB_CONTEXT_JSON | Select-Object -Property server_url, repository, run_id
          $runUrl = "{0}/{1}/actions/runs/{2}" -f $github.server_url, $github.repository, $github.run_id

          $newBody = @"
          The ``svgwg-drift`` sentinel detected drift between the baked spec catalog and upstream.

          $($env:DRIFT_DIGEST)

          Run: $runUrl
          "@

          $listIssues = {
            param($state)

            $raw = (& gh issue list --state $state --label $env:ISSUE_LABEL --limit 100 --json number,title) -join "`n"
            if ($LASTEXITCODE -ne 0) { "::error::gh issue list failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }
            if ([string]::IsNullOrWhiteSpace($raw)) { return @() }

            @($raw | ConvertFrom-Json | Where-Object { $_.title -eq $env:ISSUE_TITLE } | ForEach-Object { $_.number })
          }

          $existing = @(&$listIssues "open")

          if ($existing.Count -gt 0) {
            $number = [string]$existing[0]
            $created = "false"
            "Found existing tracking issue #{0}" -f $number
          } else {
            $url = ((& gh issue create --title $env:ISSUE_TITLE --body $newBody --label $env:ISSUE_LABEL) -join "`n").Trim()
            if ($LASTEXITCODE -ne 0) { "::error::gh issue create failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }

            $number = ($url -split "/")[-1]
            $created = "true"
            "Opened tracking issue #{0}" -f $number
          }

          "number=$number" >> $env:GITHUB_OUTPUT
          "created=$created" >> $env:GITHUB_OUTPUT

      - name: Build auto-refresh pull request body
        id: pr
        if: needs.check.outputs.any == '1'
        env:
          DRIFT_DIGEST: ${{ needs.check.outputs.digest }}
          HEAD_COMMIT: ${{ needs.check.outputs.head_commit }}
          COMPAT_TABLE: ${{ needs.check.outputs.compat_table }}
          ISSUE_NUMBER: ${{ steps.issue.outputs.number }}
        run: |
          $ErrorActionPreference = "Stop"

          $setOutput = {
            param([System.Collections.IDictionary]$kv)

            foreach ($key in $kv.Keys) {
              $value = [string]$kv[$key]

              if ($value.Contains("`n")) {
                $delimiter = [guid]::NewGuid().ToString("N")
                "$key<<$delimiter`n$value`n$delimiter" >> $env:GITHUB_OUTPUT
              } else {
                "{0}={1}" -f $key, $value >> $env:GITHUB_OUTPUT
              }
            }
          }

          $body = @"
          Automated spec catalog regeneration from the weekly **svgwg-drift** sentinel.

          $($env:DRIFT_DIGEST)

          ---

          ``svg-data-regen`` re-fetched svgwg at w3c/svgwg@$($env:HEAD_COMMIT), BCD, and web-features, and rewrote the derived catalog with fresh provenance. ``cargo test -p svg-data`` (repro + provenance gates) passed in the generating job. Review the catalog diff before merging.

          Closes #$($env:ISSUE_NUMBER)
          "@

          $commit = @("chore(spec-data): regenerate catalog from upstream", "")
          if ($env:COMPAT_TABLE) { $commit += $env:COMPAT_TABLE; $commit += "" }
          $commit += "svgwg: w3c/svgwg@{0}" -f $env:HEAD_COMMIT
          $commit += ""
          $commit += "Closes #{0}" -f $env:ISSUE_NUMBER

          &$setOutput ([ordered]@{ body = $body; commit_message = $commit -join "`n" })

      - name: Open auto-refresh pull request
        id: cpr
        if: needs.check.outputs.any == '1'
        uses: peter-evans/create-pull-request@v8
        with:
          # A PAT (or fine-grained token) with `contents: write` +
          # `pull-requests: write`, NOT the default GITHUB_TOKEN — so the
          # opened PR triggers `pull_request` CI (ci.yml) instead of being
          # inert. Add it as the `SPEC_REFRESH_PAT` repo secret.
          token: "${{ secrets.SPEC_REFRESH_PAT }}"
          base: "${{ github.event.repository.default_branch }}"
          branch: spec-data/auto-refresh
          delete-branch: true
          labels: "${{ env.ISSUE_LABEL }}"
          commit-message: ${{ steps.pr.outputs.commit_message }}
          title: "spec-data: regenerate catalog from upstream"
          body: ${{ steps.pr.outputs.body }}

      - name: Update tracking issue
        if: needs.check.outputs.any == '1' && steps.issue.outputs.created == 'false'
        env:
          DRIFT_DIGEST: ${{ needs.check.outputs.digest }}
          PR_URL: ${{ steps.cpr.outputs.pull-request-url }}
          PR_OPERATION: ${{ steps.cpr.outputs.pull-request-operation }}
          ISSUE_NUMBER: ${{ steps.issue.outputs.number }}
        run: |
          $ErrorActionPreference = "Stop"

          $github = ConvertFrom-Json $env:GITHUB_CONTEXT_JSON | Select-Object -Property server_url, repository, run_id
          $runUrl = "{0}/{1}/actions/runs/{2}" -f $github.server_url, $github.repository, $github.run_id

          $prLine = if ($env:PR_URL) {
            'The regenerated catalog was {0} as {1}, which closes this issue when merged.' -f $env:PR_OPERATION, $env:PR_URL
          } else {
            'Regeneration produced no catalog changes, so no pull request was opened.'
          }

          $body = @"
          Upstream moved again.

          $($env:DRIFT_DIGEST)

          ---

          $prLine

          Run: $runUrl
          "@

          gh issue comment $env:ISSUE_NUMBER --body $body
          if ($LASTEXITCODE -ne 0) { "::error::gh issue comment failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }

      - name: Fail when a tracked series could not be checked
        if: needs.check.outputs.errors != '0'
        env:
          ERROR_COUNT: ${{ needs.check.outputs.errors }}
          ERROR_SERIES: ${{ needs.check.outputs.error_series }}
        run: |
          $ErrorActionPreference = "Stop"

          "::error title=Unchecked spec series::{0} tracked series could not be checked ({1}). The sentinel reports no drift for them because it never reached them, not because they are current. See the run summary." -f $env:ERROR_COUNT, $env:ERROR_SERIES
          exit 1

      - name: Close tracking issue when fresh
        if: needs.check.outputs.sentinel_exit == '0' && needs.check.outputs.compat_exit == '0' && needs.check.outputs.any == '0'
        run: |
          $ErrorActionPreference = "Stop"

          $listIssues = {
            param($state)

            $raw = (& gh issue list --state $state --label $env:ISSUE_LABEL --limit 100 --json number,title) -join "`n"
            if ($LASTEXITCODE -ne 0) { "::error::gh issue list failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }
            if ([string]::IsNullOrWhiteSpace($raw)) { return @() }

            @($raw | ConvertFrom-Json | Where-Object { $_.title -eq $env:ISSUE_TITLE } | ForEach-Object { $_.number })
          }

          $comment = "Resolved: ``svgwg-drift`` now reports the baked data up to date."

          foreach ($number in @(&$listIssues "open")) {
            "Spec data is fresh again - closing #{0}" -f $number

            gh issue close $number --comment $comment
            if ($LASTEXITCODE -ne 0) { "::error::gh issue close failed (exit {0})" -f $LASTEXITCODE; exit $LASTEXITCODE }
          }

