name: runtime smoke validation
on:
  pull_request:
  push: { branches: [master] }
  workflow_dispatch:
    inputs:
      tag: { description: Existing release tag (empty selects latest), required: false, type: string }
permissions: { contents: read, actions: read }
concurrency: { group: "runtime-smoke-${{ github.ref }}", cancel-in-progress: true }

jobs:
  package:
    name: package published archives for smoke validation
    runs-on: ubuntu-latest
    timeout-minutes: 20
    outputs: { tag: "${{ steps.release.outputs.tag }}" }
    steps:
      - uses: actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0 # v7
        with: { persist-credentials: false }
      - uses: actions/setup-node@48b55a011bda9f5d6aeb4c2d9c7362e8dae4041e # v6
        with: { node-version-file: package.json, package-manager-cache: false }
      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2
      - uses: taiki-e/install-action@43aecc8d72668fbcfe75c31400bc4f890f1c5853 # v2
        with: { tool: just }
      # Packaging uses JavaScript dependencies; grammar addon builds are unrelated.
      - run: bun install --frozen-lockfile --ignore-scripts
      - name: runtime policy and workflow regressions
        run: just release-runtime-test
      - name: select existing release without building or publishing
        id: release
        env: { GH_TOKEN: "${{ github.token }}", REQUESTED_TAG: "${{ inputs.tag }}" }
        shell: node {0}
        run: |
          const requested = process.env.REQUESTED_TAG;
          if (requested && !/^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(requested)) throw new Error('Invalid requested tag');
          const tag = require('node:child_process').execFileSync('gh', ['release', 'view', ...(requested ? [requested] : []), '--json', 'tagName', '--jq', '.tagName'], { encoding: 'utf8' }).trim();
          if (!/^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(tag)) throw new Error('Invalid release tag');
          require('node:fs').appendFileSync(process.env.GITHUB_OUTPUT, `tag=${tag}\n`);
      - uses: $/.github/actions/download-archives
        with: { tag: "${{ steps.release.outputs.tag }}", token: "${{ github.token }}" }
      - name: package existing release binaries using current npm templates
        env: { RELEASE_TAG: "${{ steps.release.outputs.tag }}" }
        run: node distribution/npm/scripts/build-packages.ts --version "${RELEASE_TAG#v}"
      - name: report archive and package evidence
        env: { RELEASE_TAG: "${{ steps.release.outputs.tag }}" }
        run: node .github/actions/npm-smoke/runtime.mjs inventory
      - name: preserve modes across the artifact handoff
        run: tar -cf distribution/npm/dist.tar -C distribution/npm dist downloads
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7
        with: { name: dist, path: distribution/npm/dist.tar, retention-days: 14, if-no-files-found: error }

  runtime:
    needs: package
    uses: $/.github/workflows/runtime-smoke.yml
    with:
      tag: ${{ needs.package.outputs.tag }}
      run-id: ${{ github.run_id }}
      report-prefix: ci-runtime

